import {character,babyCharacter,defaultCast,SUPPORT,escapeText} from './characters.mjs';
const E=escapeText;
export function sceneArtwork(asset,cast=defaultCast(),{background='assets/settings/'+asset.environmentId+'.jpg',twins=false,optionId='',furnished=false,babies=0}={}){
 const id=asset.id,positive=id==='pregnancy_test_positive',clinic=asset.environmentId==='clinic',car=asset.environmentId==='showroom',leak=id==='property_water_leak';
 const panel={home:[0,0],clinic:[-900,0],showroom:[0,-600],apartment:[-900,-600]}[asset.environmentId]||[0,0];
 const companion=positive||asset.support==='partner'?cast.partner:SUPPORT[asset.support]||SUPPORT.assistant;
 const outcome=!!asset.outcomeId||!!optionId,calm=['reuse','simple','bus','warranty','compare','inspect','repair'].includes(optionId||asset.outcomeId);
 const props=positive?`<g class="test-prop" transform="translate(420 318) rotate(-15)"><rect width="71" height="19" rx="7" fill="#F5ECDD" stroke="#784C50"/><rect x="10" y="5" width="27" height="9" rx="3" fill="#DFCABD"/><path d="M18 6V13M27 6V13" stroke="#784C50" stroke-width="2"/><path d="M56 2V17" stroke="#AC6043" stroke-width="2"/></g><g class="celebrate-rays" stroke="#DAA34E" stroke-width="3"><path d="M435 180L430 163M457 181L467 164M414 191L400 183"/></g>`:id==='pregnancy_test_purchase'?`<g class="parcel" transform="translate(410 355)"><rect width="70" height="42" rx="4" fill="#F5ECDD" stroke="#AC6043"/><path d="M10 13H60M10 23H42" stroke="#697F59" stroke-width="3"/></g>`:clinic?`<g class="ultrasound" transform="translate(648 114)"><rect width="126" height="83" rx="6" fill="#24483C" stroke="#B79D83" stroke-width="5"/><path d="M18 63Q63 0 108 63Z" fill="#B79D83" opacity=".22"/><g class="scan-reveal" fill="#F5ECDD" opacity=".85"><path d="M42 47Q29 30 43 24Q59 23 57 40Q68 55 48 61Q33 62 34 52Z"/>${id==='pregnancy_twins_reveal'||twins?'<path d="M84 48Q69 34 80 27Q97 25 96 43Q104 57 87 64Q72 64 74 55Z"/>':''}</g></g>`:car?`<g class="virtual-car" transform="translate(535 362)"><path d="M-45 5L-25-39Q-12-53 29-53H106L151-13L181 0L185 48H-57L-57 16Z" fill="#24483C" stroke="#403C32" stroke-width="3"/><path d="M-16-36H31V-9H-29ZM41-36H101L132-9H41Z" fill="#B9C8B6"/><path d="M-48 14H-20M157 14H179" stroke="#DAA34E" stroke-width="8"/><circle cx="-7" cy="46" r="24" fill="#403C32"/><circle cx="136" cy="46" r="24" fill="#403C32"/><g fill="#B79D83"><circle cx="-7" cy="46" r="12"/><circle cx="136" cy="46" r="12"/></g><path d="M39 4H53M101 4H115" stroke="#B79D83" stroke-width="3"/>${id==='car_battery_failure'?'<g class="dashboard" transform="translate(35 -22)"><circle r="6" fill="#AC6043"/><path d="M-12-8H12" stroke="#DAA34E" stroke-width="3"/></g>':''}</g>${id==='car_delivery'?'<g class="keys" transform="translate(425 300)"><circle r="9" stroke="#DAA34E" stroke-width="4" fill="none"/><path d="M8 5L28 22L34 16M23 18L28 12" fill="none" stroke="#DAA34E" stroke-width="5"/></g>':''}`:leak?`<g class="rain-drops" stroke="#B79D83" stroke-width="2" opacity=".65">${Array.from({length:20},(_,n)=>`<path d="M${40+n*11} ${35+n%4*30}l-8 26"/>`).join('')}</g><path class="water-drop" d="M440 85Q425 110 440 115Q455 110 440 85" fill="#B79D83"/><g class="bucket" transform="translate(420 400)"><path d="M0 0H60L52 49H8Z" fill="#AC6043" stroke="#784C50" stroke-width="2"/><path d="M3 10Q30-20 57 10" stroke="#B79D83" stroke-width="3" fill="none"/></g><g class="quote-paper" transform="translate(640 330) rotate(-8)"><rect width="60" height="75" fill="#F5ECDD"/><path d="M10 17H50M10 30H48M10 44H40" stroke="#697F59" stroke-width="2"/></g>`:id==='baby_preparation'?`<g class="nursery" transform="translate(550 335)"><path d="M0 5H150V85H0Z" fill="#B79D83" stroke="#634B3B" stroke-width="3"/><path d="M10 12H140V68H10Z" fill="#F5ECDD"/><path d="M0 0V98M150 0V98M25 15V70M50 15V70M75 15V70M100 15V70M125 15V70" stroke="#AC6043" stroke-width="5"/><path d="M15 58Q70 30 135 58" fill="#697F59"/>${babies?babyCharacter({x:babies>1?48:75,y:30,skin:cast.player.skin})+(babies>1?babyCharacter({x:105,y:30,skin:cast.partner.skin,blanket:'#AC6043'}):''):''}</g>`:`<g class="story-object" transform="translate(620 366)"><rect width="100" height="65" rx="4" fill="${id==='business_first_order'||id==='living_move_in'?'#B79D83':'#F5ECDD'}" stroke="#784C50" stroke-width="2"/><path d="M10 15H90M10 28H70M10 41H80" stroke="#697F59" stroke-width="3"/><path d="M50 0V65" stroke="#DAA34E" stroke-width="3"/></g>`;
 return `<svg class="story-stage-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 600" role="img" aria-label="${E(asset.title)} — ${E(asset.description)}"><defs><clipPath id="stage-clip"><rect width="900" height="600" rx="16"/></clipPath><filter id="paper-grain"><feTurbulence type="fractalNoise" baseFrequency=".72" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".11"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter><linearGradient id="stage-shade" x2="0" y2="1"><stop stop-color="#24483C" stop-opacity="0"/><stop offset="1" stop-color="#24483C" stop-opacity=".26"/></linearGradient></defs><g clip-path="url(#stage-clip)"><rect width="900" height="600" fill="#F5ECDD"/><g class="painted-setting"><image href="${E(background)}" x="0" y="0" width="900" height="600" preserveAspectRatio="none"/></g><rect y="390" width="900" height="210" fill="url(#stage-shade)"/><g class="scene-cast" filter="url(#paper-grain)">${character(cast.player,{id:'player',x:positive?365:290,y:490,scale:1.45,expression:outcome?(calm?'neutral':'happy'):positive?'neutral':leak||id==='car_battery_failure'?'confused':'neutral'})}${character(companion,{id:positive?'partner':asset.support,x:positive?535:470,y:490,scale:1.47,expression:outcome?'happy':positive?'neutral':'neutral'})}${props}${outcome?choiceProp(optionId||asset.outcomeId):''}${furnished?'<path d="M795 480V400M770 420Q810 385 830 425" stroke="#697F59" stroke-width="16" fill="none"/>':''}</g><g class="outcome-mark" transform="translate(760 94)"><circle r="32" fill="${calm?'#697F59':'#DAA34E'}" opacity=".85"/><path d="M-14 0L-3 11L16-13" stroke="#F5ECDD" stroke-width="5" fill="none"/></g><rect width="900" height="600" fill="#B79D83" opacity=".035" pointer-events="none"/></g></svg>`;
}
export function sceneBeats(asset,cast=defaultCast(),language='en',optionTitle=''){
 const zh=language==='zh',say=(en,cn)=>zh?cn:en;
 if(asset.id==='pregnancy_test_positive')return [
 {at:0,mood:'anticipation',speaker:cast.player.name,text:say('One quiet moment. One little test.','安静的一刻，小小的测试。')},
 {at:1000,mood:'reveal',speaker:cast.partner.name,text:say('Wait... is that what I think it is?','等等……这真的是我想的那样吗？')},
 {at:2000,mood:'surprise',speaker:cast.player.name,text:say('Looks like our little adventure is about to begin.','看来我们的小小冒险就要开始了。')},
 {at:3000,mood:'happy',speaker:say('Narrator','旁白'),text:say('In this fictional life, a new chapter begins.','在这段虚构人生中，新的一章开始了。')},
 {at:4500,mood:'celebrate',speaker:cast.partner.name,text:say('We’ll learn, one step at a time.','我们一步一步来，慢慢学习。')},
 {at:5500,mood:'embrace',speaker:say('Narrator','旁白'),text:say('A warm embrace, and a story still to be discovered.','一个温暖的拥抱，故事仍待揭晓。')}];
 const battery=asset.id==='car_battery_failure',leak=asset.id==='property_water_leak',twins=asset.id==='pregnancy_twins_reveal';
 if(asset.category==='completion')return [{at:0,mood:'happy',speaker:say('Narrator','旁白'),text:say('A page lived. Your savings checkpoint is complete.','体验完一页，储蓄点已完成。')},{at:2500,mood:'celebrate',speaker:cast.player.name,text:say('One small step, and a little more confidence.','一小步，多一份信心。')},{at:5500,mood:'happy',speaker:say('Narrator','旁白'),text:say('The next page stays sealed until you choose to open it.','下一页保持封存，等你选择打开。')}];
 if(asset.category==='outcome')return [{at:0,mood:'consider',speaker:cast.player.name,text:optionTitle||say('Let’s take this next step thoughtfully.','让我们用心踏出下一步。')},{at:1400,mood:['reuse','simple','compare','warranty'].includes(asset.outcomeId)?'consider':'gesture',speaker:SUPPORT[asset.support]?.name||cast.partner.name,text:say(`Your choice: ${optionTitle||asset.outcomeId}. The next page shows its itemized plan.`,`你的选择：${optionTitle||asset.outcomeId}。下一页显示明细计划。`)},{at:2700,mood:'happy',speaker:say('Narrator','旁白'),text:say('A fictional decision. Your real savings stay in your control.','虚构的决定，真实储蓄仍由你掌控。')}];
 return [{at:0,mood:'enter',speaker:say('Narrator','旁白'),text:zh?say('','平常的一天，新的一页。'):asset.description},
 {at:1100,mood:battery?'ignition':leak?'drip':'consider',speaker:cast.player.name,text:battery?say('Let’s try the ignition.','试着启动一下。'):leak?say('Is that a drip? I’ll bring the bucket.','是漏水吗？我去拿水桶。'):say('Let’s have a closer look.','让我们仔细看看。')},
 {at:2300,mood:battery?'failure':twins?'reveal':leak?'bucket':'gesture',speaker:SUPPORT[asset.support]?.name||cast.partner.name,text:twins?say('Two little ones in this story. We’ll talk through the possibilities.','故事里有两个小宝宝，我们会一起讨论各种可能。'):battery?say('It won’t start. Let’s check what is actually needed.','无法启动。先检查实际需要处理什么。'):leak?say('We can inspect the source and prepare a separate quotation.','我们可以检查源头，并提供独立报价。'):say('There are a few ways to approach this.','我们有几种应对方式。')},
 {at:4000,mood:'consider',speaker:cast.player.name,text:say('We can choose the next step together.','我们一起选择下一步。')}];
}

function choiceProp(id){const paper='<rect width="44" height="58" rx="2" fill="#F5ECDD" stroke="#784C50"/><path d="M7 13H36M7 23H32M7 33H36" stroke="#697F59" stroke-width="2"/>';if(id==='compare')return '<g class="decision-prop" transform="translate(624 273)">'+paper+'<g transform="translate(53 8) rotate(8)">'+paper+'</g></g>';if(id==='warranty'||id==='inspect'||id==='review')return '<g class="decision-prop" transform="translate(630 270)">'+paper+'<path d="M10 43L17 49L34 37" stroke="#697F59" stroke-width="3" fill="none"/></g>';if(id==='replace'||id==='repair')return '<g class="decision-prop" transform="translate(620 287)"><rect width="55" height="38" fill="#697F59" stroke="#24483C"/><path d="M12 0V-5H21V0M34 0V-5H43V0M14 15H25M20 9V21M36 15H45" stroke="#DAA34E" stroke-width="3"/></g>';if(['reuse','simple','family','bus'].includes(id))return '<g class="decision-prop" transform="translate(630 290)"><path d="M0 35V0H50V35Z" fill="#B79D83" stroke="#784C50"/><path d="M25 0V35M0 13H50" stroke="#F5ECDD" stroke-width="3"/><path d="M60 26Q45 0 70-10Q88 8 60 26" fill="#697F59"/></g>';return '<g class="decision-prop" transform="translate(630 282)">'+paper+'</g>';}
